icons.update({alias:icons[target] for alias,target in {'pencil':'square-pen','trash-2':'trash','shield':'shield-check','book-open':'file','sliders-horizontal':'settings'}.items()})
keep=['info','wrench','plug','folder','search','plus','chevron-down','chevron-right','chevron-left','refresh-cw','pencil','trash-2','sun','moon','settings','bot','globe','shield','chart-no-axes-column','git-branch','layers','book-open','square-terminal','file','database','x','check','loader-circle','circle-alert','copy','layout-grid','sparkles','monitor','circle','sliders-horizontal','arrow-left']
